import { DatePipe } from '@angular/common';
import {
    Component,
    computed,
    ElementRef,
    forwardRef,
    OnInit,
    signal,
    viewChild,
} from '@angular/core';
import {
    ControlValueAccessor,
    FormControl,
    FormGroup,
    NG_VALUE_ACCESSOR,
    ReactiveFormsModule,
    Validators,
} from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { AsyncHandler } from '@placeos/common';
import { addYears, setMonth } from 'date-fns';

export interface PaymentCardDetails {
    card_number: string;
    cardholder: string;
    cvv: string;
    exp_month: string;
    exp_year: string;
}

const BLANK_CARD = { card_number: '                ', cardholder: '', cvv: '' };
const DATE_PIPE = new DatePipe('en-us', '');

@Component({
    selector: 'card-input-field',
    template: `
        <form [formGroup]="details" (window:keyup)="onInput($event)">
            <div class="flex flex-col">
                <label for="card-number">Card Number</label>
                <div
                    id="card-number"
                    role="textbox"
                    [attr.aria-disabled]="disabled"
                    [attr.tabindex]="disabled ? -1 : 0"
                    class="border-base-200 focus-within:border-base-200 relative mb-4 flex h-12 w-full items-center rounded-sm border p-2 font-mono focus-within:shadow-sm"
                    (focus)="focusInput()"
                    (focusout)="blurInput()"
                >
                    <pre class="flex-1">{{ card_display() }}</pre>
                    <input
                        #input
                        class="absolute hidden"
                        type="tel"
                        [value]="details.value.card_number?.trim()"
                        (keydown)="(false)"
                        maxlength="17"
                    />
                    @if (card_type()) {
                        <img
                            [src]="'assets/icons/' + card_type() + '.svg'"
                            class="h-8"
                        />
                    }
                </div>
            </div>
            <div class="flex flex-1 flex-col">
                <label for="cardholder">Name on Card</label>
                <mat-form-field appearance="outline">
                    <input
                        name="cardholder"
                        id="cardholder"
                        matInput
                        placeholder="Mr John Smith"
                        formControlName="cardholder"
                    />
                    <mat-error>Cardholder name is required</mat-error>
                </mat-form-field>
            </div>
            <div class="flex items-center space-x-2">
                <div class="flex w-1/4 flex-1 flex-col">
                    <label for="exp-month">Expiry Month</label>
                    <mat-form-field appearance="outline">
                        <mat-select
                            id="exp-month"
                            placeholder="MM"
                            formControlName="exp_month"
                        >
                            @for (item of months; track item) {
                                <mat-option [value]="item[0]">
                                    {{ item[1] }} ({{ item[0] }})
                                </mat-option>
                            }
                        </mat-select>
                        <mat-error>Expiry month is required</mat-error>
                    </mat-form-field>
                </div>
                <div class="flex w-1/4 flex-1 flex-col">
                    <label for="exp-year">Expiry Year</label>
                    <mat-form-field appearance="outline">
                        <mat-select
                            id="exp-year"
                            placeholder="YYYY"
                            formControlName="exp_year"
                        >
                            @for (item of years; track item) {
                                <mat-option [value]="item">{{
                                    item
                                }}</mat-option>
                            }
                        </mat-select>
                        <mat-error>Expiry year is required</mat-error>
                    </mat-form-field>
                </div>
                <div class="flex flex-col">
                    <label for="cvv">CVV</label>
                    <mat-form-field appearance="outline" class="w-20">
                        <input
                            name="cvv"
                            id="cvv"
                            matInput
                            formControlName="cvv"
                            maxlength="4"
                        />
                        <mat-error>Invalid security code</mat-error>
                    </mat-form-field>
                </div>
            </div>
        </form>
    `,
    styles: [
        `
            mat-form-field {
                height: 3.25rem;
            }
        `,
    ],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            /* istanbul ignore next */
            useExisting: forwardRef(() => CardInputFieldComponent),
            multi: true,
        },
    ],
    imports: [
        MatFormFieldModule,
        MatInputModule,
        MatSelectModule,
        ReactiveFormsModule,
    ],
})
export class CardInputFieldComponent
    extends AsyncHandler
    implements ControlValueAccessor, OnInit
{
    public details = new FormGroup({
        card_number: new FormControl(Array(16).fill('X').join()),
        cardholder: new FormControl(''),
        exp_month: new FormControl(''),
        exp_year: new FormControl(''),
        cvv: new FormControl('', [
            Validators.minLength(3),
            Validators.maxLength(4),
        ]),
    });
    public disabled = false;

    public readonly months = Array(12)
        .fill(0)
        .map((_, idx) => [
            DATE_PIPE.transform(setMonth(Date.now(), idx), 'MM'),
            DATE_PIPE.transform(setMonth(Date.now(), idx), 'MMM'),
        ]);
    public readonly years = Array(12)
        .fill(0)
        .map((_, idx) =>
            DATE_PIPE.transform(addYears(Date.now(), idx), 'yyyy'),
        );
    public readonly digits = Array(16).fill(0);
    private readonly _index = signal(0);
    private readonly _card_number = signal(BLANK_CARD.card_number);
    private readonly card_focused = signal(false);

    private readonly _input_el =
        viewChild.required<ElementRef<HTMLInputElement>>('input');

    private _onChange?: (_: PaymentCardDetails) => void;
    private _onTouch?: () => void;

    public readonly is_amex = computed(() => {
        const no = this._card_number();
        return no.startsWith('3');
    });

    public readonly card_type = computed(() => {
        const no = this._card_number();
        if (no.startsWith('3')) return 'amex';
        if (no.startsWith('4')) return 'visa';
        if (no.startsWith('5')) return 'mastercard';
        return '';
    });

    public readonly card_display = computed(() => {
        let no = this._card_number();
        if (this.card_focused()) {
            const index = this._index();
            no = no.substring(0, index) + '⯐' + no.substring(index + 1);
        }
        return this.is_amex()
            ? `${no.substring(0, 4)}-${no.substring(4, 10)}-${no.substring(10)}`
            : `${no.substring(0, 4)}-${no.substring(4, 8)}-${no.substring(
                  8,
                  12,
              )}-${no.substring(12)}`;
    });

    public ngOnInit() {
        this.subscription(
            'changes',
            this.details.valueChanges.subscribe(() =>
                this.timeout('update', () => {
                    const value = this.details.getRawValue();
                    this._card_number.set(value.card_number || '');
                    this.setValue(value);
                }),
            ),
        );
    }

    public focusInput() {
        if (this.disabled) return;
        this._input_el().nativeElement.focus();
        this.card_focused.set(true);
        this._index.set(this._input_el().nativeElement.selectionStart || 0);
    }

    public blurInput() {
        this.card_focused.set(false);
        this._onTouch?.();
    }

    public onInput(event: KeyboardEvent) {
        if (!event || this.disabled || !this.card_focused()) return;
        const idx = this._index();
        if (idx < 0 || idx > 16) return;
        let card_number =
            this.details.value.card_number ?? BLANK_CARD.card_number;
        if (
            (event.code.startsWith('Digit') ||
                event.code.startsWith('Numpad')) &&
            idx < (this.is_amex() ? 15 : 16)
        ) {
            card_number =
                card_number.substring(0, idx) +
                event.key +
                card_number.substring(idx + 1);
            this.details.patchValue({ card_number });
            this._focusChange(idx, 1);
        } else if (event.code === 'Backspace' && idx > 0) {
            card_number =
                card_number.substring(0, idx - 1) +
                ' ' +
                card_number.substring(idx);
            this.details.patchValue({ card_number });
            this._focusChange(idx, -1);
        } else if (event.code === 'ArrowLeft') {
            this._focusChange(idx, -1);
        } else if (event.code === 'ArrowRight' && card_number[idx] !== ' ') {
            this._focusChange(idx, 1);
        }
    }

    private _focusChange(idx: number, dir: 1 | -1) {
        this._index.set(Math.min(16, Math.max(0, idx + dir)));
    }

    /**
     * Update the form field value
     * @param new_value New value to set on the form field
     */
    public setValue(new_value: PaymentCardDetails) {
        if (this._onChange) this._onChange(new_value);
    }

    /**
     * Update local value when form control value is changed
     * @param value The new value for the component
     */
    public writeValue(value?: PaymentCardDetails) {
        const details = value || BLANK_CARD;
        this._card_number.set(details.card_number || '');
        this.details.patchValue(details, { emitEvent: false });
    }

    public readonly registerOnChange = (fn: (_: PaymentCardDetails) => void) =>
        (this._onChange = fn);
    public readonly registerOnTouched = (fn: () => void) =>
        (this._onTouch = fn);
    public setDisabledState(state: boolean) {
        this.disabled = state;
        if (state) this.details.disable({ emitEvent: false });
        else this.details.enable({ emitEvent: false });
    }
}
